def calculate_S2(N):
    # S2 = (N^2 - 1) / 2
    return (N**2 - 1) / 2

# Check for small N > 6
N_values = range(7, 16)
results = {}
for N in N_values:
    results[N] = calculate_S2(N)

print("Calculated values of S2 = (N^2 - 1)/2 for N=7 to N=15:")
for N, S2 in results.items():
    print(f"N={N}, S2={S2}")

def check_condition(N):
    if N <= 0:
        return False

    M = N + 1

    # Required value for Sigma_mod
    required_sigma_mod = (M**2 * (N - 1)) / 2

    if required_sigma_mod != int(required_sigma_mod):
        return False, "Not integer"

    # Actual calculation of Sigma_mod: sum(ab mod M) for 1 <= a, b <= N
    sigma_mod = 0
    for a in range(1, N + 1):
        for b in range(1, N + 1):
            sigma_mod += (a * b) % M

    return sigma_mod == required_sigma_mod, sigma_mod, required_sigma_mod

tests = [1, 2, 3, 4, 5]
results = {}
for N in tests:
    match, actual, required = check_condition(N)
    results[N] = (match, actual, required)

print(results)

